INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4446707, 640955, 83032, '<td valign="top">nice and clean...you handled it well...good job.</td>', 'nice and clean...you handled it well...good job.', '2008-02-01 12:37:39.000000', NULL, 1),
(4446711, 630611, 34659, '<td valign="top">WOW...  This is just stunning.</td>', 'WOW...  This is just stunning.', '2008-02-01 12:40:00.000000', NULL, 1),
(4446713, 637591, 83032, '<td valign="top">nice shot but something don''t feel right in his right eye and there should be a little more depth of field.  Maybe if you darkened the entire print slightly???  You got the fur on the hat.  Good luck with it.</td>', 'nice shot but something don''t feel right in his right eye and there should be a little more depth of field.  Maybe if you darkened the entire print slightly???  You got the fur on the hat.  Good luck with it.', '2008-02-01 12:40:51.000000', NULL, 1),
(4446715, 640014, 83032, '<td valign="top">wow...heck of a shot...love the color</td>', 'wow...heck of a shot...love the color', '2008-02-01 12:41:32.000000', NULL, 1),
(4446725, 640664, 71608, '<td valign="top">I get a little bored with landscapes sometimes, but I love the added interest of the fisherman here! He even seems to be leaning with the clouds, lovely :)</td>', 'I get a little bored with landscapes sometimes, but I love the added interest of the fisherman here! He even seems to be leaning with the clouds, lovely :)', '2008-02-01 12:44:31.000000', NULL, 1),
(4446726, 640449, 83032, '<td valign="top">It''s a little dark in the upper middle and I wish I could see the eyes...even though the animal looks asleep. Overall, I do like the photo....how can you not like warm, gentle puppies.  Good luck.</td>', 'It''s a little dark in the upper middle and I wish I could see the eyes...even though the animal looks asleep. Overall, I do like the photo....how can you not like warm, gentle puppies.  Good luck.', '2008-02-01 12:45:02.000000', NULL, 1),
(4446728, 628674, 71608, '<td valign="top">This is a LOVELY photo, however not being able to see the babies face is a little disconcerting for some reason... very well done otherwise!</td>', 'This is a LOVELY photo, however not being able to see the babies face is a little disconcerting for some reason... very well done otherwise!', '2008-02-01 12:45:41.000000', NULL, 1),
(4446730, 638264, 71608, '<td valign="top">Street theatre? This reminds me of someone I used to work for in street theatre, lol. Great capture!!</td>', 'Street theatre? This reminds me of someone I used to work for in street theatre, lol. Great capture!!', '2008-02-01 12:46:42.000000', NULL, 1),
(4446751, 638760, 54033, '<td valign="top">why is it so small in size?? I wish it was bigger lovely photo 9 any ways</td>', 'why is it so small in size?? I wish it was bigger lovely photo 9 any ways', '2008-02-01 13:01:20.000000', NULL, 1),
(4446779, 640969, 37845, '<td valign="top">I like the black and white conversion here... nice midtone greys.</td>', 'I like the black and white conversion here... nice midtone greys.', '2008-02-01 13:12:06.000000', NULL, 1),
(4446780, 633017, 80831, '<td valign="top">u are certainly talented in astrophotography...beautiful shot of the Horsehead nebula!...must be that star gazer guy....lol... 9</td>', 'u are certainly talented in astrophotography...beautiful shot of the Horsehead nebula!...must be that star gazer guy....lol... 9', '2008-02-01 13:12:18.000000', NULL, 1),
(4446786, 640762, 37845, '<td valign="top">I think I would like the photo better if it didnt have the retaining wall in the background... takes away from the nature of the shot.</td>', 'I think I would like the photo better if it didnt have the retaining wall in the background... takes away from the nature of the shot.', '2008-02-01 13:13:07.000000', NULL, 1),
(4446787, 639834, 37845, '<td valign="top">What a cool looking building.</td>', 'What a cool looking building.', '2008-02-01 13:13:26.000000', NULL, 1),
(4446791, 640639, 37845, '<td valign="top">The non-smoker in me wants to criticize the photo, but I have to say that the lighting is perfect. The only thing that may have added to this would be a trail of smoke coming from the cigarette. 7</td>', 'The non-smoker in me wants to criticize the photo, but I have to say that the lighting is perfect. The only thing that may have added to this would be a trail of smoke coming from the cigarette. 7', '2008-02-01 13:14:22.000000', NULL, 1),
(4446792, 640171, 37845, '<td valign="top">I love the still water in this.</td>', 'I love the still water in this.', '2008-02-01 13:14:55.000000', NULL, 1),
(4446793, 635686, 83032, '<td valign="top">Really nice shot...but the the two folds in the background under her left elbow is a distraction. I know that''s being picky but to me it''s a problem.  You did really good with her skin tones and texture.  The hair could use a little light to get the shine.  You handled the eyes pretty well with her not looking at the camera....I know that''s hard to do but the eye on the left has a dark shadow.</td>', 'Really nice shot...but the the two folds in the background under her left elbow is a distraction. I know that''s being picky but to me it''s a problem.  You did really good with her skin tones and texture.  The hair could use a little light to get the shine.  You handled the eyes pretty well with her not looking at the camera....I know that''s hard to do but the eye on the left has a dark shadow.', '2008-02-01 13:15:13.000000', NULL, 1),
(4446794, 638542, 37845, '<td valign="top">Nice cool feel to this... love the blue.</td>', 'Nice cool feel to this... love the blue.', '2008-02-01 13:15:15.000000', NULL, 1),
(4446797, 640329, 37845, '<td valign="top">Look very rustic. This shot might have been better in HDR, with more light on the street level, and with the railing in the bottom left cropped out.</td>', 'Look very rustic. This shot might have been better in HDR, with more light on the street level, and with the railing in the bottom left cropped out.', '2008-02-01 13:16:22.000000', NULL, 1),
(4446817, 633017, 66267, '<td valign="top">Nice capture of a difficult subject.</td>', 'Nice capture of a difficult subject.', '2008-02-01 13:22:03.000000', NULL, 1),
(4446819, 639998, 37845, '<td valign="top">Good attempt. Could use a boost in contrast though.</td>', 'Good attempt. Could use a boost in contrast though.', '2008-02-01 13:22:40.000000', NULL, 1),
(4446821, 634878, 37845, '<td valign="top">Looks like a new type of marathon.</td>', 'Looks like a new type of marathon.', '2008-02-01 13:22:55.000000', NULL, 1),
(4446822, 637932, 37845, '<td valign="top">Nice closeup. Like the oranges and greens.</td>', 'Nice closeup. Like the oranges and greens.', '2008-02-01 13:23:17.000000', NULL, 1),
