(4446827, 632953, 37845, '<td valign="top">Whoa... what a unique shot... well done.</td>', 'Whoa... what a unique shot... well done.', '2008-02-01 13:24:22.000000', NULL, 1),
(4446830, 635266, 48389, '<td valign="top">Not voting in this but couldn''t resist...<br/> <br/>What were you thinking?!! ;o) Someone should really give you a smack in the face for trying to make the great DPC voters think this is real! :-P ;o) Seriously, you know what I think ;o) Though, bet you can''t tell me 1 thing that I told you to change and it looks like you didn''t...</td>', 'Not voting in this but couldn''t resist... What were you thinking?!! ;o) Someone should really give you a smack in the face for trying to make the great DPC voters think this is real! :-P ;o) Seriously, you know what I think ;o) Though, bet you can''t tell me 1 thing that I told you to change and it looks like you didn''t...', '2008-02-01 13:25:03.000000', NULL, 1),
(4446831, 640751, 37845, '<td valign="top">Cool shot. Not sure if its just my monitor, but some of the scales look blown out. 6</td>', 'Cool shot. Not sure if its just my monitor, but some of the scales look blown out. 6', '2008-02-01 13:25:06.000000', NULL, 1),
(4446832, 640838, 37845, '<td valign="top">I like the simplicity of this shot, and your choice of black and white.</td>', 'I like the simplicity of this shot, and your choice of black and white.', '2008-02-01 13:25:25.000000', NULL, 1),
(4446840, 637401, 37845, '<td valign="top">I like shots like these. My only suggestion would be to crop out the tracks in the bottom. I find that I spend half my time looking at them (and they take me to the right of the image), and the other half looking at the skyline. Just my opinion, but a little distracting. 6</td>', 'I like shots like these. My only suggestion would be to crop out the tracks in the bottom. I find that I spend half my time looking at them (and they take me to the right of the image), and the other half looking at the skyline. Just my opinion, but a little distracting. 6', '2008-02-01 13:27:02.000000', NULL, 1),
(4446842, 640792, 37845, '<td valign="top">Your focus here is outstanding, and the green is a great frame. On technicals alone, this photo is amazing. I just wish I could feel more passionate about the subject. 8 from me.</td>', 'Your focus here is outstanding, and the green is a great frame. On technicals alone, this photo is amazing. I just wish I could feel more passionate about the subject. 8 from me.', '2008-02-01 13:28:15.000000', NULL, 1),
(4446843, 630488, 37845, '<td valign="top">Interesting shot. The lines definetly draw the viewer toward the horizon. Nice black and white conversion as well.</td>', 'Interesting shot. The lines definetly draw the viewer toward the horizon. Nice black and white conversion as well.', '2008-02-01 13:28:51.000000', NULL, 1),
(4446848, 639964, 37845, '<td valign="top">I wish this was composed a little differently, so that the guy in the background was completely in the frame. His expression adds a lot to this shot.</td>', 'I wish this was composed a little differently, so that the guy in the background was completely in the frame. His expression adds a lot to this shot.', '2008-02-01 13:29:53.000000', NULL, 1),
