INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4466699, 637390, 19248, '<td valign="top">Very nice.  Love the colors, &amp; composition.</td>', 'Very nice.  Love the colors, & composition.', '2008-02-06 23:01:52.000000', NULL, 1),
(4466700, 630534, 83313, '<td valign="top">The subject does not quite stand out enough from the background of the same color. Of course, that background is the flower of the same color. Maybe a little extra adjustments would make them stand out better.</td>', 'The subject does not quite stand out enough from the background of the same color. Of course, that background is the flower of the same color. Maybe a little extra adjustments would make them stand out better.', '2008-02-06 23:03:08.000000', NULL, 1),
(4466706, 640401, 83313, '<td valign="top">Except for some blown highlights just behind her ear, this is a very nice portrait.</td>', 'Except for some blown highlights just behind her ear, this is a very nice portrait.', '2008-02-06 23:04:01.000000', NULL, 1),
(4466712, 630855, 83313, '<td valign="top">Looks like she is waiting for you to take the picture already. Nice PP on this.</td>', 'Looks like she is waiting for you to take the picture already. Nice PP on this.', '2008-02-06 23:05:32.000000', NULL, 1),
(4466719, 640459, 83313, '<td valign="top">Nice catch of jsut the right moment. Only thing that bothers me is the slight sepia in the sky, while the snow looks like a straight b/w.</td>', 'Nice catch of jsut the right moment. Only thing that bothers me is the slight sepia in the sky, while the snow looks like a straight b/w.', '2008-02-06 23:06:41.000000', NULL, 1),
(4466725, 637592, 83313, '<td valign="top">Gives me an impression of some very wide open spaces, with nothing around for miles.</td>', 'Gives me an impression of some very wide open spaces, with nothing around for miles.', '2008-02-06 23:07:29.000000', NULL, 1),
(4466875, 637979, 75034, '<td valign="top">How frigen long did you scrub the fridge for this shot?? Now that I''ve asked that I like the composition and the lighting in your shot. The reflection and the tilt add to the shot for me almost like movement. Nicely done IMHO. Hope you do well with this shot. 8</td>', 'How frigen long did you scrub the fridge for this shot?? Now that I''ve asked that I like the composition and the lighting in your shot. The reflection and the tilt add to the shot for me almost like movement. Nicely done IMHO. Hope you do well with this shot. 8', '2008-02-07 00:04:22.000000', NULL, 1),
(4466887, 640639, 28882, '<td valign="top">nice portrait.   i like the squinty eyes.  the lighing in great too.</td>', 'nice portrait.   i like the squinty eyes.  the lighing in great too.', '2008-02-07 00:09:05.000000', NULL, 1),
(4467000, 630103, 7743, '<td valign="top">Though a good idea compositionally speaking the processing of the skin has gone way overboard.  Looks too plastic.</td>', 'Though a good idea compositionally speaking the processing of the skin has gone way overboard.  Looks too plastic.', '2008-02-07 00:46:25.000000', NULL, 1),
(4467072, 640578, 87424, '<td valign="top">Amazing and enthralling.</td>', 'Amazing and enthralling.', '2008-02-07 01:10:38.000000', NULL, 1),
(4467164, 640600, 78021, '<td valign="top">Awsome sharpness on the bird, too bad that branch is in the way.</td>', 'Awsome sharpness on the bird, too bad that branch is in the way.', '2008-02-07 02:03:18.000000', NULL, 1),
(4467169, 640372, 78021, '<td valign="top">Love all the different textures.</td>', 'Love all the different textures.', '2008-02-07 02:05:56.000000', NULL, 1),
(4467221, 640844, 19831, '<td valign="top">Great eye on this one. Very nice choice of subject. I like the centered approach for the composition, there is good symmetry here, and the single black ''s'' at top offers nice opposition, and tension in the shot, a good ''break up'' for the scene. However, it is just a little ''off'', just enough to seem careless, and not fully thought out. I think in a shot like this, it can be greatly strengthened by really nailing the symmetry present, and emphasizing and driving home the centered comp. With all the lines that are here, going right to the edge of the frame, it is easy to see that it is not ''straight'', or in line. Also, the distance from the edge of both sides of the frame, to the edge of the windows is not the same. I would say it looks like your shooting position could of been just a step or two to the left, and really squared it all up tight. I mean, this is just so close to that, it seems like that is the intent. This is just not ''off'' enought to seem like it was the chosen POV. But if it was, then ignore me :-) Still a nice shot.</td>', 'Great eye on this one. Very nice choice of subject. I like the centered approach for the composition, there is good symmetry here, and the single black ''s'' at top offers nice opposition, and tension in the shot, a good ''break up'' for the scene. However, it is just a little ''off'', just enough to seem careless, and not fully thought out. I think in a shot like this, it can be greatly strengthened by really nailing the symmetry present, and emphasizing and driving home the centered comp. With all the lines that are here, going right to the edge of the frame, it is easy to see that it is not ''straight'', or in line. Also, the distance from the edge of both sides of the frame, to the edge of the windows is not the same. I would say it looks like your shooting position could of been just a step or two to the left, and really squared it all up tight. I mean, this is just so close to that, it seems like that is the intent. This is just not ''off'' enought to seem like it was the chosen POV. But if it was, then ignore me :-) Still a nice shot.', '2008-02-07 02:38:04.000000', NULL, 1),
(4467234, 640564, 19831, '<td valign="top">Great cat pic! Nice composition. Well done.</td>', 'Great cat pic! Nice composition. Well done.', '2008-02-07 02:42:37.000000', NULL, 1),
(4467237, 640553, 19831, '<td valign="top">Love the took! Good composition too.</td>', 'Love the took! Good composition too.', '2008-02-07 02:43:58.000000', NULL, 1),
(4467243, 638141, 19831, '<td valign="top">Beautiful cat pic! And a beautiful cat. Very nice job on the lighting and composition. Good job.</td>', 'Beautiful cat pic! And a beautiful cat. Very nice job on the lighting and composition. Good job.', '2008-02-07 02:45:36.000000', NULL, 1),
(4467258, 638283, 19831, '<td valign="top">Very cool use of reflections here. Great image.</td>', 'Very cool use of reflections here. Great image.', '2008-02-07 02:52:41.000000', NULL, 1),
(4467260, 639576, 19831, '<td valign="top">Nice subject. Great composition. Good choice for b/w, and nice job on it, good tones. Nice work.</td>', 'Nice subject. Great composition. Good choice for b/w, and nice job on it, good tones. Nice work.', '2008-02-07 02:54:05.000000', NULL, 1),
(4467267, 639918, 19831, '<td valign="top">Makes a cool abstract. Good job on comp and exposure. Curious as to what the source lights are. I like these kinds of shots.</td>', 'Makes a cool abstract. Good job on comp and exposure. Curious as to what the source lights are. I like these kinds of shots.', '2008-02-07 02:56:12.000000', NULL, 1),
(4467272, 638604, 19831, '<td valign="top">Great capture. You really nailed it in catching them in this grouping. Makes for a good composition. Nice work!</td>', 'Great capture. You really nailed it in catching them in this grouping. Makes for a good composition. Nice work!', '2008-02-07 03:00:27.000000', NULL, 1),
(4467274, 640639, 19831, '<td valign="top">Very cool image! I like it. Great lighting and tones. Perhaps it could be a little bit stronger compositionally with a wee bit of the left cropped off? Maybe not. Nice work.</td>', 'Very cool image! I like it. Great lighting and tones. Perhaps it could be a little bit stronger compositionally with a wee bit of the left cropped off? Maybe not. Nice work.', '2008-02-07 03:04:00.000000', NULL, 1),
(4467288, 639445, 19831, '<td valign="top">Good detail. Nice backlighting.</td>', 'Good detail. Nice backlighting.', '2008-02-07 03:16:56.000000', NULL, 1),
(4467297, 640754, 19831, '<td valign="top">Just when I''ve been thinking that seeing the silky long exp. water shots is starting to get a bit tedius, you''ve come along with this fresh approach and created this stunning abstract. Wonderful composition. Great editing. Love the rich, earthy tones/colors. A great title too. I love this shot! Very nice work, very nice. Thank-you for creating it.</td>', 'Just when I''ve been thinking that seeing the silky long exp. water shots is starting to get a bit tedius, you''ve come along with this fresh approach and created this stunning abstract. Wonderful composition. Great editing. Love the rich, earthy tones/colors. A great title too. I love this shot! Very nice work, very nice. Thank-you for creating it.', '2008-02-07 03:33:15.000000', NULL, 1),
(4467343, 631317, 7786, '<td valign="top">Brilliant image. The stop time here works like magic! If the you had a deeper DOF so that the whole cards would be in focus i would be my winner in this challenge.</td>', 'Brilliant image. The stop time here works like magic! If the you had a deeper DOF so that the whole cards would be in focus i would be my winner in this challenge.', '2008-02-07 05:00:45.000000', NULL, 1),
(4467501, 637905, 56828, '<td valign="top">Great DOF.</td>', 'Great DOF.', '2008-02-07 07:38:23.000000', NULL, 1),
(4467606, 637910, 15711, '<td valign="top">Seems to have too much Neat Image.  It makes her pretty face look more like plastic.  I might crop it just below her collar bone and have it more in the landscape orientation. ;~)</td>', 'Seems to have too much Neat Image.  It makes her pretty face look more like plastic.  I might crop it just below her collar bone and have it more in the landscape orientation. ;~)', '2008-02-07 08:51:16.000000', NULL, 1),
(4467611, 635266, 15711, '<td valign="top">I know the right glove is part of the story, but it distracts to my eye.  I''d like it cropped so all we see is the left one and have it in the portrait orientation. That guy looks awfully old to be a boxer. WOW</td>', 'I know the right glove is part of the story, but it distracts to my eye.  I''d like it cropped so all we see is the left one and have it in the portrait orientation. That guy looks awfully old to be a boxer. WOW', '2008-02-07 08:53:40.000000', NULL, 1),
