(4468543, 632914, 39850, '<td valign="top">5 - Nice simplicity, good composition.  Overall looks a little ''squat'' - so perhaps a little more width either side, not sure.  720 also if the quality was there.</td>', '5 - Nice simplicity, good composition.  Overall looks a little ''squat'' - so perhaps a little more width either side, not sure.  720 also if the quality was there.', '2008-02-07 14:40:21.000000', NULL, 1),
(4468548, 639334, 39850, '<td valign="top">8 - Nice.  ''Aww''.  Shame the writing (especially ''SUNDAY'') wasn''t closer to the face.  Apologies in advance if wrong, but this also looks like it needs a whisker (no pun) up on the left.  The b&amp;w works very well.</td>', '8 - Nice.  ''Aww''.  Shame the writing (especially ''SUNDAY'') wasn''t closer to the face.  Apologies in advance if wrong, but this also looks like it needs a whisker (no pun) up on the left.  The b&w works very well.', '2008-02-07 14:42:05.000000', NULL, 1),
(4468553, 630103, 39850, '<td valign="top">Think I see what you were going for, but there are too many elements which distract - the shirt, the writing on the shirt, the ship/rig in the background, crooked horizon, blown sky, the pose/facial expression - but mostly that this looks ''spriteish''.</td>', 'Think I see what you were going for, but there are too many elements which distract - the shirt, the writing on the shirt, the ship/rig in the background, crooked horizon, blown sky, the pose/facial expression - but mostly that this looks ''spriteish''.', '2008-02-07 14:44:39.000000', NULL, 1),
(4468560, 637932, 39850, '<td valign="top">5 - Nice ''little scene'', nice backdrop - good potential - like to be able to discern the details in the face more - perhaps the contrast is a touch too strong, not sure.</td>', '5 - Nice ''little scene'', nice backdrop - good potential - like to be able to discern the details in the face more - perhaps the contrast is a touch too strong, not sure.', '2008-02-07 14:46:26.000000', NULL, 1),
