(4468572, 637372, 39850, '<td valign="top">7 - Nice image.  Wonder whether a fraction less on the right make it even stronger.  Difficult, but be nice to discern more iris too... but perhaps that is just ''another image''.</td>', '7 - Nice image.  Wonder whether a fraction less on the right make it even stronger.  Difficult, but be nice to discern more iris too... but perhaps that is just ''another image''.', '2008-02-07 14:52:03.000000', NULL, 1),
(4468575, 633208, 39850, '<td valign="top">6 - Nice scene.  Unusual image, the composition could be intentional, but wonder about less at the bottom/fore to ''showcase'' a little more.  If the quality was there, 720 as well.</td>', '6 - Nice scene.  Unusual image, the composition could be intentional, but wonder about less at the bottom/fore to ''showcase'' a little more.  If the quality was there, 720 as well.', '2008-02-07 14:53:39.000000', NULL, 1),
(4468583, 632953, 39850, '<td valign="top">8 - Oo.  Nice.  The black frame dominates too much though - in my opinion.</td>', '8 - Oo.  Nice.  The black frame dominates too much though - in my opinion.', '2008-02-07 14:58:07.000000', NULL, 1),
