(4468646, 636116, 30712, '<td valign="top">The lighting here is amazing - for me almost other worldly.</td>', 'The lighting here is amazing - for me almost other worldly.', '2008-02-07 15:28:19.000000', NULL, 1),
(4468648, 640823, 30712, '<td valign="top">A truly beautiful image - so sharp and detailed.</td>', 'A truly beautiful image - so sharp and detailed.', '2008-02-07 15:29:10.000000', NULL, 1),
(4468649, 638137, 30712, '<td valign="top">The dramatic shape and form of the foreground and the contrast of light make this a truly magnificent shot.  Mind you, I''m impressed by the midground and background as well.</td>', 'The dramatic shape and form of the foreground and the contrast of light make this a truly magnificent shot.  Mind you, I''m impressed by the midground and background as well.', '2008-02-07 15:31:11.000000', NULL, 1),
(4468656, 637390, 30712, '<td valign="top">Nature isn''t doing badly with the light, is it?  I like the depth of field and the detail throughout the image.  The glow from the lighthouse itself tones in so well with the glow on the horizon.</td>', 'Nature isn''t doing badly with the light, is it?  I like the depth of field and the detail throughout the image.  The glow from the lighthouse itself tones in so well with the glow on the horizon.', '2008-02-07 15:34:19.000000', NULL, 1),
(4468659, 640187, 30712, '<td valign="top">This picture tells such a story.</td>', 'This picture tells such a story.', '2008-02-07 15:34:54.000000', NULL, 1),
(4468665, 640493, 30712, '<td valign="top">Sheer drama.  A seascape with high hills very well captured.  The small figures and the white foam trails make this special.</td>', 'Sheer drama.  A seascape with high hills very well captured.  The small figures and the white foam trails make this special.', '2008-02-07 15:36:41.000000', NULL, 1),
(4468851, 638471, 42495, '<td valign="top">Nice colors, indeed, but the bug seems a bit blurred to me.</td>', 'Nice colors, indeed, but the bug seems a bit blurred to me.', '2008-02-07 16:46:48.000000', NULL, 1),
