(4469739, 635619, 50695, '<td valign="top">as a doglover I take umbrage at your title, but this is a tremendous capture. Stunning.</td>', 'as a doglover I take umbrage at your title, but this is a tremendous capture. Stunning.', '2008-02-07 22:38:05.000000', NULL, 1),
