(4469742, 635468, 50695, '<td valign="top">beautiful pastels and how can I resist that title? great brushstrokes, too.</td>', 'beautiful pastels and how can I resist that title? great brushstrokes, too.', '2008-02-07 22:38:23.000000', NULL, 1),
