(4469751, 640020, 83313, '<td valign="top">Nice scene and subject here, though the tones seem a little on the low contrast side. Maybe a touch too centered.</td>', 'Nice scene and subject here, though the tones seem a little on the low contrast side. Maybe a touch too centered.', '2008-02-07 22:39:21.000000', NULL, 1),
(4469759, 640764, 50695, '<td valign="top">My head says I''ve seen this picture before, such a common theme, how many silhouettes on the beach have I seen? But my heart says no I have never seen this ocean before, this ocean is of another world, another water. My heart says, almost deafeningly loud, blue.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/bluepost.jpg'', strrpos(''//blackyak.com/dpc/bluepost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/bluepost.jpg"/></td>', 'My head says I''ve seen this picture before, such a common theme, how many silhouettes on the beach have I seen? But my heart says no I have never seen this ocean before, this ocean is of another world, another water. My heart says, almost deafeningly loud, blue. ', '2008-02-07 22:41:43.000000', NULL, 1),
(4469766, 640564, 83313, '<td valign="top">A basic pet shot, but extremely well done. Clear, good color and lots of detail. The pattern of the fur provides a nice s-curve that leads my eye up to the cats face. I want to give this kitty a scratch behind the ears.</td>', 'A basic pet shot, but extremely well done. Clear, good color and lots of detail. The pattern of the fur provides a nice s-curve that leads my eye up to the cats face. I want to give this kitty a scratch behind the ears.', '2008-02-07 22:43:12.000000', NULL, 1),
(4469775, 630479, 50695, '<td valign="top">great texture and tones and an interesting composition of horizontal layers.<br/> <br/>I keep coming back to this. The pelicans are impossibly big. The light on the tire is insanely beautiful. Pollution has never looked so good. But most important, this is an image I''ve never seen before. Posthumous Red Ribbon.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/redpost.jpg'', strrpos(''//blackyak.com/dpc/redpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/redpost.jpg"/></td>', 'great texture and tones and an interesting composition of horizontal layers. I keep coming back to this. The pelicans are impossibly big. The light on the tire is insanely beautiful. Pollution has never looked so good. But most important, this is an image I''ve never seen before. Posthumous Red Ribbon. ', '2008-02-07 22:46:41.000000', NULL, 1),
(4469780, 639253, 50695, '<td valign="top">Very well done. It looks like a sculpture, or a Man Ray photo, or both.<br/> <br/>Posthumous Yellow Ribbon <img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'Very well done. It looks like a sculpture, or a Man Ray photo, or both. Posthumous Yellow Ribbon ', '2008-02-07 22:48:09.000000', NULL, 1),
(4469781, 629582, 50695, '<td valign="top">This is in some uncomfortable place between Rembrandt and Van Gogh. There''s no going back now. 10.</td>', 'This is in some uncomfortable place between Rembrandt and Van Gogh. There''s no going back now. 10.', '2008-02-07 22:48:34.000000', NULL, 1),
(4469782, 640941, 50695, '<td valign="top">the box between life and not-life. a coffin. a body revealing its soul. 10.</td>', 'the box between life and not-life. a coffin. a body revealing its soul. 10.', '2008-02-07 22:48:41.000000', NULL, 1),
(4469783, 640592, 50695, '<td valign="top">this picture makes me happy. I love the light, and how it is so easy on my eyes. the picture is easy like Sunday morning. 10.</td>', 'this picture makes me happy. I love the light, and how it is so easy on my eyes. the picture is easy like Sunday morning. 10.', '2008-02-07 22:48:47.000000', NULL, 1),
(4469786, 640179, 83313, '<td valign="top">Well done. You caught all the detail in that match. I gotta learn how to do these.</td>', 'Well done. You caught all the detail in that match. I gotta learn how to do these.', '2008-02-07 22:52:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4469793, 633427, 50695, '<td valign="top">Brilliant. 10. Aw hell, I was going to pass this by for a ribbon for some perverse reason, like it''s too good or something, or it just looks too much like a ribbon, or it''s just too Ed Clarke, and technically I''ve given out three ribbons already, but my system allows for ties so I''m giving this a Posthumous yellow ribbon. Yes, I know you were robbed, but I''ve never claimed to be fair.<br/> <br/><img alt="'' . substr(''//blackyak.com/dpc/yellowpost.jpg'', strrpos(''//blackyak.com/dpc/yellowpost.jpg'', ''/'') + 1) . ''" border="0" src="//blackyak.com/dpc/yellowpost.jpg"/></td>', 'Brilliant. 10. Aw hell, I was going to pass this by for a ribbon for some perverse reason, like it''s too good or something, or it just looks too much like a ribbon, or it''s just too Ed Clarke, and technically I''ve given out three ribbons already, but my system allows for ties so I''m giving this a Posthumous yellow ribbon. Yes, I know you were robbed, but I''ve never claimed to be fair. ', '2008-02-07 22:58:09.000000', NULL, 1),
(4469876, 640952, 64989, '<td valign="top">Absolutely stunning!  I had to let out a breath when I saw it.  I can find nothing to change. A 10!</td>', 'Absolutely stunning!  I had to let out a breath when I saw it.  I can find nothing to change. A 10!', '2008-02-07 23:35:18.000000', NULL, 1),
(4469882, 633017, 77838, '<td valign="top">Such an awesome image.  I''m impressed everytime I see these, especially for how clear they are.  Very nice photo, I like it.  -BB<br/> <br/> <br/>I wonder if this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=84124" rel="nofollow" target="_blank">jlanoue</a>, but not sure.</td>', 'Such an awesome image.  I''m impressed everytime I see these, especially for how clear they are.  Very nice photo, I like it.  -BB  I wonder if this is  jlanoue, but not sure.', '2008-02-07 23:36:58.000000', NULL, 1),
(4469885, 640435, 23430, '<td valign="top">Nicely lit. Good background, colours and clarity. Good luck.</td>', 'Nicely lit. Good background, colours and clarity. Good luck.', '2008-02-07 23:37:32.000000', NULL, 1),
(4469888, 640664, 23430, '<td valign="top">Beautiful scene very well composed.</td>', 'Beautiful scene very well composed.', '2008-02-07 23:38:14.000000', NULL, 1),
(4469905, 637932, 77838, '<td valign="top">I love the orange and green colors here.  It''s more of a lime green and light orange.  The out-of-focus waterfall in the background give this a little bit more oomph than just an ordinary "butterfly" image.  Nice job with DOF too.  -BB<br/> <br/>PS.  I wonder if anybody else will comment on the waterfall?...</td>', 'I love the orange and green colors here.  It''s more of a lime green and light orange.  The out-of-focus waterfall in the background give this a little bit more oomph than just an ordinary "butterfly" image.  Nice job with DOF too.  -BB PS.  I wonder if anybody else will comment on the waterfall?...', '2008-02-07 23:45:03.000000', NULL, 1),
(4469913, 640854, 77838, '<td valign="top">This is a great "stopped motion" image.  Great clarity and focus.  The only thing that I wish was a little darker was the sand right behing the bird.  I can see all of the surf but it''s really washed out, kind of a bummer but still a great photo. 7 from me -BB</td>', 'This is a great "stopped motion" image.  Great clarity and focus.  The only thing that I wish was a little darker was the sand right behing the bird.  I can see all of the surf but it''s really washed out, kind of a bummer but still a great photo. 7 from me -BB', '2008-02-07 23:48:59.000000', NULL, 1),
(4469917, 640677, 77838, '<td valign="top">D for dimpled chin!  I love the duotones here too, very nice framing. -BB</td>', 'D for dimpled chin!  I love the duotones here too, very nice framing. -BB', '2008-02-07 23:49:46.000000', NULL, 1),
(4469922, 640763, 77838, '<td valign="top">Nice "stopped motion"; I like the wingtip in the water also.  The framing is a bit tight for me but since you can still see the whole bird it''s all good. -BB</td>', 'Nice "stopped motion"; I like the wingtip in the water also.  The framing is a bit tight for me but since you can still see the whole bird it''s all good. -BB', '2008-02-07 23:52:07.000000', NULL, 1),
(4469925, 634878, 77838, '<td valign="top">Sweet "time-lapse" photo, you did good on this. -BB</td>', 'Sweet "time-lapse" photo, you did good on this. -BB', '2008-02-07 23:53:03.000000', NULL, 1),
(4469928, 639380, 77838, '<td valign="top">Awww, ...very cool photo.  Let me guess cousins?...twins?  The pink and blue compliment each other well.  Very nice. -BB</td>', 'Awww, ...very cool photo.  Let me guess cousins?...twins?  The pink and blue compliment each other well.  Very nice. -BB', '2008-02-07 23:55:23.000000', NULL, 1),
(4469930, 640823, 77838, '<td valign="top">Great clarity. -BB</td>', 'Great clarity. -BB', '2008-02-07 23:55:50.000000', NULL, 1),
(4469932, 640943, 77838, '<td valign="top">Great use of "negative space" -BB</td>', 'Great use of "negative space" -BB', '2008-02-07 23:56:11.000000', NULL, 1),
(4469935, 639491, 77838, '<td valign="top">Very nice colors; I like the mist over the surf also. -BB</td>', 'Very nice colors; I like the mist over the surf also. -BB', '2008-02-07 23:56:57.000000', NULL, 1),
(4469938, 640481, 77838, '<td valign="top">Wow, looks cold but most of all I like the deep blue hue to the water and sky.  I like how you was able to get the clouds to acutally be "white". -BB</td>', 'Wow, looks cold but most of all I like the deep blue hue to the water and sky.  I like how you was able to get the clouds to acutally be "white". -BB', '2008-02-07 23:58:29.000000', NULL, 1),
