(5007907, 640635, 62318, '<td valign="top">Very unique skyline. Wonderful light and symmetry created by the reflection. Truly a different take on the usual.</td>', 'Very unique skyline. Wonderful light and symmetry created by the reflection. Truly a different take on the usual.', '2008-10-14 12:59:53.000000', NULL, 0),
(5033519, 629530, 66635, '<td valign="top">Awesome!</td>', 'Awesome!', '2008-10-30 19:06:16.000000', NULL, 0),
(5055365, 634259, 16912, '<td valign="top">Gordon, viewing the thumbnail my initial thought was ''hope'' so was not suprised to see it was the title!<br/> <br/>Forgetting for a moment that it should have been a 6+ and easily a top 50 shot not 100+ I think you have a great portrait here. I love the softness and almost high key effect, its adds to the naivety thus hope of your subject. I want to be able to see what baby is bewildered by and the bg is spot on!</td>', 'Gordon, viewing the thumbnail my initial thought was ''hope'' so was not suprised to see it was the title! Forgetting for a moment that it should have been a 6+ and easily a top 50 shot not 100+ I think you have a great portrait here. I love the softness and almost high key effect, its adds to the naivety thus hope of your subject. I want to be able to see what baby is bewildered by and the bg is spot on!', '2008-11-10 16:39:38.000000', NULL, 0),
(5106030, 638283, 23484, '<td valign="top">I love this. Great abstract.</td>', 'I love this. Great abstract.', '2008-12-04 14:21:01.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5106391, 640955, 63398, '<td valign="top">Really nice snow scene! Terrific eye candy.</td>', 'Really nice snow scene! Terrific eye candy.', '2008-12-04 16:45:56.000000', NULL, 0),
(5117698, 640857, 86447, '<td valign="top">What a cutie!   I like the muted colors and the composition.</td>', 'What a cutie!   I like the muted colors and the composition.', '2008-12-08 16:47:51.000000', NULL, 0),
(5122440, 639960, 20577, '<td valign="top">Underrated... what kills me about DPC is that everything has to be razor sharp... if this picture would have been done without the soft focus it wouldn''t have the impact that it does. Seriously people, there is a thing called soft focus...</td>', 'Underrated... what kills me about DPC is that everything has to be razor sharp... if this picture would have been done without the soft focus it wouldn''t have the impact that it does. Seriously people, there is a thing called soft focus...', '2008-12-10 11:37:38.000000', NULL, 0),
(5130852, 628977, 3214, '<td valign="top">One would have always have to try very hard in order to ribbon on a free study, but people freely give good scores in them in comparison to one of the themed challenges.  <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=52713" rel="nofollow" target="_blank">scarbrd</a>''s photo has more eye appeal because of both the angle at which it was taken (eliminating uninteresting background) and the visual "pop" of his post-processing.  Wonderful concept and awwww-factor!</td>', 'One would have always have to try very hard in order to ribbon on a free study, but people freely give good scores in them in comparison to one of the themed challenges.   scarbrd''s photo has more eye appeal because of both the angle at which it was taken (eliminating uninteresting background) and the visual "pop" of his post-processing.  Wonderful concept and awwww-factor!', '2008-12-14 20:19:06.000000', NULL, 0),
